SWITCH.original:
switch (fileWaitFlag) {
case 4:
    KillTimer(rootWnd, 0);
    if (LoadGame(0, 0) != 0) {
        SetMapPlane(MePlane);
        if (MePlane == 0)
            SetYardMode(YardMode);
        else if (!win_IsWinOpen(0x100))
            YardToMap();
        if (CenterEdit(MeLocX, MeLocY) != 0) {
            if (win_IsWinOpen(0x100)) {
                MSClipStart(win_hwnd[1]);
                EraseMapCursor();
                DrawMapCursor();
                MSClipEnd();
            }
            editForce = 1;
            UpdateEdit();
        }
        for (i = 0; i < 7; i++) {
            bookMark[i].object = -1;
            bookMark[i].plane = 0;
            bookMark[i].x = 0;
            bookMark[i].y = 0;
            bookMark[i].flags = 0;
            win_SetButtonBitmaps(0x2218 + i, 0x3899 + i, 0x3867 + i);
            win_SetObjSelectedState(0x2218 + i, 0);
            win_SetButtonBitmaps(0x2313 + i, 0x3899 + i, 0x3867 + i);
            win_SetObjSelectedState(0x2313 + i, 0);
        }
    } else if (CurGameType == -1 && NewGame(0) < 0) {
        CleanUp();
        goto menu_done;
    }
    break;
case 5:
    KillTimer(rootWnd, 0);
    SaveGame(1);
    break;
case 6:
    KillTimer(rootWnd, 0);
    SaveGame(0);
    break;
case 8:
    KillTimer(rootWnd, 0);
    if (MenuQuit() != 0) {
        CleanUp();
        goto menu_done;
    }
    break;
default:
    goto menu_done;
   }

